from pathlib import Path
import scipy.io as sio
import numpy as np
root=Path('/app/data')
def desc(x,name='root',depth=0,maxdepth=4):
    ind='  '*depth
    if isinstance(x,dict):
        print(f'{ind}{name}: dict keys={list(x.keys())}')
        if depth<maxdepth:
            for k,v in x.items(): desc(v,k,depth+1,maxdepth)
    elif isinstance(x,np.ndarray):
        print(f'{ind}{name}: ndarray shape={x.shape} dtype={x.dtype}')
        if x.dtype==object and x.size and depth<maxdepth:
            desc(x.flat[0],name+'[0]',depth+1,maxdepth)
    elif isinstance(x,(list,tuple)):
        print(f'{ind}{name}: {type(x).__name__} len={len(x)}')
        if x and depth<maxdepth: desc(x[0],name+'[0]',depth+1,maxdepth)
    else:
        val=repr(x)
        print(f'{ind}{name}: {type(x).__name__} {val[:100]}')
for d in sorted(p for p in root.iterdir() if p.is_dir()):
    groups={}
    for p in sorted(d.glob('*.mat')):
        groups.setdefault(p.name.split('_')[0],p)
    for pref,p in groups.items():
        print(f'\n===== {p.relative_to(root)} =====')
        try:
            m=sio.loadmat(p,simplify_cells=True)
            for k,v in m.items():
                if not k.startswith('__'): desc(v,k)
        except Exception as e: print('ERROR',type(e).__name__,e)
